const fs = require('node:fs');
const path = require('node:path');
const { spawnSync, execFileSync } = require('node:child_process');

const scratch = path.resolve('_scratch/hook-repair');
const runtimeLabel = process.env.HOOK_REPAIR_RUNTIME || 'initial';
const commands = [
  ['typecheck', 'npx', ['tsc', '--noEmit']],
  ['typecheck-spec', 'npm', ['run', 'typecheck:spec']],
  ['lint', 'npm', ['run', 'lint']],
  ['loc', 'npm', ['run', 'check:ts-max-loc']],
  ['ui-hints', 'npm', ['run', 'check:ui-hints']],
  ['build-main', 'npm', ['run', 'build:main']],
  ['build-renderer', 'npm', ['run', 'build:renderer']],
  ['full-suite', 'npm', ['run', 'test:quiet']],
];
for (const [label, command, args] of commands) {
  if (label === 'full-suite') {
    const load = require('node:os').loadavg();
    fs.writeFileSync(path.join(scratch, `full-preflight-${runtimeLabel}.json`), JSON.stringify({
      at: new Date().toISOString(), load, uptime: execFileSync('uptime', { encoding: 'utf8' }),
    }, null, 2));
    if (load.some(value => value > 30)) throw new Error('Full suite deferred: host load exceeds 30');
  }
  const log = path.join(scratch, `${label}-${runtimeLabel}.log`);
  const fd = fs.openSync(log, 'w');
  const startedAt = new Date().toISOString();
  console.log(`Starting ${label}`);
  const result = spawnSync(command, args, {
    stdio: ['ignore', fd, fd],
    env: { ...process.env, AIO_TEST_SUMMARY: '0', AIO_TEST_NO_CACHE: '1', AIO_TEST_OUT_SUFFIX: `hook-full-${runtimeLabel}` },
  });
  fs.closeSync(fd);
  fs.appendFileSync(path.join(scratch, 'commands.jsonl'), JSON.stringify({
    command: [command, ...args], startedAt, endedAt: new Date().toISOString(),
    status: result.status, signal: result.signal, error: result.error?.message, log,
    nodeVersion: process.version, nodeExecutable: process.execPath,
  }) + '\n');
  console.log(`${label}: exit ${result.status}; log ${log}`);
  if (result.error || result.signal || result.status !== 0) {
    console.log(fs.readFileSync(log, 'utf8').split('\n').slice(-100).join('\n'));
    process.exitCode = result.status || 1;
    break;
  }
}

const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const { execFileSync, spawnSync } = require('node:child_process');

const scratch = path.resolve('_scratch/hook-repair');
const realEnv = { ...process.env, GIT_OPTIONAL_LOCKS: '0' };
const git = args => execFileSync('git', args, { env: realEnv, encoding: 'utf8' });
const hash = bytes => crypto.createHash('sha256').update(bytes).digest('hex');
const indexPath = git(['rev-parse', '--git-path', 'index']).trim();
const base = git(['merge-base', 'main', 'HEAD']).trim();
const sourceList = output => output.trim().split('\n').filter(file => /\.(ts|js|mjs|cjs)$/.test(file));
const files = sourceList(git(['diff', '--name-only', '--diff-filter=ACMR', base, '--', 'src', 'scripts']));
const committed = new Set(sourceList(git(['diff', '--name-only', '--diff-filter=ACMR', base, 'HEAD', '--', 'src', 'scripts'])));
const beforeBytes = hash(fs.readFileSync(indexPath));
const beforeEntries = hash(git(['ls-files', '--stage', '-z']));
const beforeSources = files.map(file => ({ file, sha256: hash(fs.readFileSync(file)) }));
const temporaryIndex = path.join(scratch, 'hook.index');
const env = { ...realEnv, GIT_INDEX_FILE: temporaryIndex, AIO_TEST_SUMMARY: '0' };
const prepareOnly = process.argv.includes('--prepare-only');
const prefix = prepareOnly ? 'selection-check' : 'pre-commit';
const stagedFiles = () => JSON.parse(execFileSync(process.execPath, ['-e',
  'console.log(JSON.stringify(require("./scripts/test-staged.js").getStagedTestRelatedFiles()))',
], { env, encoding: 'utf8' }));
let status = 1;
const startedAt = new Date().toISOString();
try {
  execFileSync('git', ['read-tree', 'HEAD'], { env });
  const indexFixture = [];
  for (const file of files) {
    if (committed.has(file)) {
      // Selection-only fixture: --cached compares HEAD, so committed paths
      // must differ from HEAD in the disposable index. Builds/tests still
      // read the untouched CURRENT working tree. This index is never committed.
      const baseEntry = git(['ls-tree', base, '--', file]);
      const headEntry = git(['ls-tree', 'HEAD', '--', file]);
      const mode = /^(\d+) /.exec(headEntry)[1];
      const blob = baseEntry ? /^\d+ blob ([a-f0-9]+)\t/.exec(baseEntry)[1]
        : 'e69de29bb2d1d6434b8b29ae775ad8c2e48c5391';
      execFileSync('git', ['cat-file', '-e', blob], { env });
      execFileSync('git', ['update-index', '--cacheinfo', `${mode},${blob},${file}`], { env });
      indexFixture.push({ file, mode, blob, representedBy: baseEntry ? 'base blob' : 'existing empty blob for added path' });
    } else {
      execFileSync('git', ['add', '--', file], { env });
      indexFixture.push({ file, representedBy: 'current uncommitted repair' });
    }
  }
  const actualSelection = stagedFiles();
  if (JSON.stringify([...actualSelection].sort()) !== JSON.stringify([...files].sort())) {
    throw new Error('Disposable index did not select every intended source path');
  }
  let result = { status: 0, signal: null };
  let buildDirectoryInitiallyAbsent = null;
  const log = path.join(scratch, `${prefix}.log`);
  if (!prepareOnly) {
    fs.rmSync('dist', { recursive: true, force: true });
    buildDirectoryInitiallyAbsent = !fs.existsSync('dist');
    const fd = fs.openSync(log, 'w');
    result = spawnSync('/bin/sh', ['.githooks/pre-commit'], { env, stdio: ['ignore', fd, fd] });
    fs.closeSync(fd);
  }
  status = result.error || result.signal ? 1 : result.status ?? 1;
  const afterBytes = hash(fs.readFileSync(indexPath));
  const afterEntries = hash(git(['ls-files', '--stage', '-z']));
  const receipt = {
    command: prepareOnly ? 'selection-only preparation' : ['/bin/sh', '.githooks/pre-commit'],
    startedAt, endedAt: new Date().toISOString(), status, signal: result.signal, error: result.error?.message,
    expectedSourceSelection: files, actualSourceSelectionBeforeHook: actualSelection,
    actualSourceSelectionAfterHook: stagedFiles(), indexFixture, temporaryIndex: true, prepareOnly,
    fixturePurpose: 'Path selection only; builds and tests read unchanged current source, never the index blobs',
    buildDirectoryInitiallyAbsent, base, nodeVersion: process.version, nodeExecutable: process.execPath,
    workerProduced: fs.existsSync('dist/main/cli/spawn-worker/cli-spawn-worker-main.js'),
    realIndexBytesUnchanged: beforeBytes === afterBytes,
    realIndexEntriesUnchanged: beforeEntries === afterEntries,
    realIndexUnchanged: beforeBytes === afterBytes && beforeEntries === afterEntries,
    realIndexHashes: { beforeBytes, afterBytes, beforeEntries, afterEntries },
    currentSourceUnchanged: beforeSources.every(row => hash(fs.readFileSync(row.file)) === row.sha256),
    sourceHashes: beforeSources, log: prepareOnly ? null : log,
  };
  fs.writeFileSync(path.join(scratch, `${prefix}-receipt.json`), JSON.stringify(receipt, null, 2));
  if (!prepareOnly) console.log(fs.readFileSync(log, 'utf8').split('\n').slice(-24).join('\n'));
  console.log(JSON.stringify({ status, selection: actualSelection.length, realIndexUnchanged: receipt.realIndexUnchanged }));
  if (!receipt.realIndexUnchanged || !receipt.currentSourceUnchanged) status = 1;
} finally {
  fs.rmSync(temporaryIndex, { force: true });
}
process.exitCode = status;

const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const zlib = require('node:zlib');
const { execFileSync } = require('node:child_process');

const root = process.cwd();
const scratch = path.resolve('_scratch/hook-repair');
const evidence = path.resolve('docs/plans/2026-09-27-livetest-agent-runtime-residuals_evidence/2026-10-27-hook-repair');
const report = '/Users/suas/work/orchestrat0r/ai-orchestrator/docs/plans/2026-09-27-livetest-agent-runtime-residuals_livetest.md';
const hash = bytes => crypto.createHash('sha256').update(bytes).digest('hex');
fs.mkdirSync(evidence, { recursive: true });

const files = [
  ...fs.readdirSync(scratch).filter(name => /\.(log|json|jsonl|txt)$/.test(name)).map(name => path.join(scratch, name)),
  ...fs.readdirSync('_scratch').filter(name => /^test-(run|results)\.hook-.*\.(log|json)$/.test(name)).map(name => path.resolve('_scratch', name)),
];
const retention = [];
for (const file of files) {
  const original = fs.readFileSync(file);
  let replacements = 0;
  let text = original.toString('utf8');
  for (const pattern of [
    /\b(?:Bearer|Basic)\s+[A-Za-z0-9_./+=-]+/gi,
    /\b(?:sk-|gh[pousr]_|github_pat_|xoxb-|xoxp-)[A-Za-z0-9_-]{16,}\b/g,
    /\beyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\b/g,
    /\b(?:AKIA|ASIA)[A-Z0-9]{16}\b/g,
    /\bya29\.[A-Za-z0-9_-]{12,}\b/g,
  ]) {
    text = text.replace(pattern, () => { replacements++; return '[REDACTED]'; });
  }
  text = text.replace(/((?:"|')?\b(?:token|accessToken|refreshToken|apiKey|api_key|clientSecret|password|secret|authorization|cookie)\b(?:"|')?\s*[:=]\s*["'])[^"'\r\n]*(["'])/gi,
    (_match, prefix, suffix) => { replacements++; return `${prefix}[REDACTED]${suffix}`; });
  if (file.endsWith('.json')) JSON.parse(text);
  const retained = Buffer.from(text);
  const compressed = file.endsWith('.log') || retained.length > 65536;
  const name = path.basename(file) + (compressed ? '.gz' : '');
  fs.writeFileSync(path.join(evidence, name), compressed ? zlib.gzipSync(retained) : retained);
  retention.push({ source: path.relative(root, file), artifact: name, originalBytes: original.length,
    retainedBytes: retained.length, originalSha256: hash(original), retainedSha256: hash(retained), compressed, redactions: replacements });
}
fs.writeFileSync(path.join(evidence, 'retention-receipt.json'), JSON.stringify(retention, null, 2));

const base = execFileSync('git', ['merge-base', 'main', 'HEAD'], { encoding: 'utf8' }).trim();
const sourcePaths = execFileSync('git', ['diff', '--name-only', base, '--', 'src', 'scripts'], { encoding: 'utf8' })
  .trim().split('\n').filter(Boolean);
const paths = [...new Set([
  ...sourcePaths, '.githooks/pre-commit', 'scripts/run-git-hook.js', 'scripts/run-related-tests.mjs',
  'docs/generated/architecture-inventory.json', 'docs/plans/livetest-remediation-register.md',
  'package.json', 'package-lock.json', 'vitest.config.ts', 'tsconfig.electron.json', report,
])];
const compiledPaths = fs.readdirSync('dist/main/cli/spawn-worker')
  .filter(name => name.endsWith('.js')).map(name => path.join('dist/main/cli/spawn-worker', name));
fs.writeFileSync(path.join(evidence, 'pre-cleanup-source-seal.json'), JSON.stringify({
  at: new Date().toISOString(), base,
  head: execFileSync('git', ['rev-parse', 'HEAD'], { encoding: 'utf8' }).trim(),
  sources: paths.map(file => ({ path: file, sha256: hash(fs.readFileSync(file)) })),
  compiled: compiledPaths.map(file => ({ path: file, sha256: hash(fs.readFileSync(file)) })),
  recipes: ['verify.cjs', 'run-hook.cjs', 'retain.cjs', 'cleanup.cjs'].map(name => ({ name, source: fs.readFileSync(path.join(scratch, name), 'utf8') })),
}, null, 2));
console.log(JSON.stringify({ evidence, retainedFiles: files.length, redactions: retention.reduce((sum, row) => sum + row.redactions, 0) }));

const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const zlib = require('node:zlib');
const { execFileSync } = require('node:child_process');

const evidence = path.resolve('docs/plans/2026-09-27-livetest-agent-runtime-residuals_evidence/2026-10-27-hook-repair');
const hash = bytes => crypto.createHash('sha256').update(bytes).digest('hex');
const readJson = file => JSON.parse(fs.readFileSync(path.join(evidence, file), 'utf8'));
const seal = readJson('pre-cleanup-source-seal.json');
if (!fs.readFileSync(path.join(evidence, 'independent-review-final.txt'), 'utf8').startsWith('VERDICT: PASS')) {
  throw new Error('Independent PASS must be retained before cleanup');
}
const validated = readJson('retention-receipt.json').map(row => {
  const bytes = fs.readFileSync(path.join(evidence, row.artifact));
  const plain = row.compressed ? zlib.gunzipSync(bytes) : bytes;
  if (hash(plain) !== row.retainedSha256) throw new Error(`Retention hash mismatch: ${row.artifact}`);
  return row.artifact;
});
for (const row of [...seal.sources, ...seal.compiled]) {
  if (hash(fs.readFileSync(row.path)) !== row.sha256) throw new Error(`Pre-cleanup seal mismatch: ${row.path}`);
}
const preservedCache = 'node_modules/.vite/vitest/57e8a7776d6892a83f2a49678f8141f4fb883e62/results.json';
const preservedCacheHash = hash(fs.readFileSync(preservedCache));
const removed = [
  'dist',
  'node_modules/.vite/vitest/da39a3ee5e6b4b0d3255bfef95601890afd80709',
  ...fs.readdirSync('_scratch').filter(name => /^test-(run|results)\.hook-/.test(name)).map(name => path.join('_scratch', name)),
  '_scratch/hook-repair',
];
for (const file of removed) fs.rmSync(file, { recursive: true, force: true });
const git = args => execFileSync('git', args, { encoding: 'utf8', env: { ...process.env, GIT_OPTIONAL_LOCKS: '0' } });
const stagedPaths = git(['diff', '--cached', '--name-only']).trim();
if (stagedPaths) throw new Error('Unexpected staged work after cleanup; preserve it for investigation');
execFileSync('git', ['diff', '--check'], { env: { ...process.env, GIT_OPTIONAL_LOCKS: '0' } });
const receipt = {
  at: new Date().toISOString(), retainedArtifactsValidated: validated,
  removed: removed.map(file => ({ path: file, absent: !fs.existsSync(file) })),
  preservedCache: { path: preservedCache, beforeSha256: preservedCacheHash, afterSha256: hash(fs.readFileSync(preservedCache)) },
  suppliedDependenciesPreserved: fs.existsSync('node_modules'),
  remainingScratch: fs.readdirSync('_scratch'),
  stagedPaths, status: git(['status', '--short']), branch: git(['branch', '--show-current']).trim(),
  head: git(['rev-parse', 'HEAD']).trim(), worktrees: git(['worktree', 'list', '--porcelain']),
  branches: git(['branch', '--list']),
  isolatedAppProfileAbsent: !fs.existsSync('/tmp/aio-lt-queue-3af326de'),
  runtimeScope: 'No app, account session, browser binary, database cluster, dependency install or copied checkout created in this repair; stopped commands exited normally.',
};
fs.writeFileSync(path.join(evidence, 'cleanup-receipt.json'), JSON.stringify(receipt, null, 2));
if (receipt.removed.some(row => !row.absent) || receipt.preservedCache.beforeSha256 !== receipt.preservedCache.afterSha256) {
  throw new Error('Cleanup invariant failed');
}
console.log(JSON.stringify({ removedPaths: removed.length, stagedPaths, remainingScratch: receipt.remainingScratch, suppliedDependenciesPreserved: true }));
